      context.sharedContext,
      context.routeMatch,
      context.parsedRequestHeaders,
      context.serverActionRequestMetadata,
      context.stagedFallbackParams,
      process.env.__NEXT_DEV_SERVER ? createDevResponseLifecycle(res) : null
